using Microsoft.VisualStudio.TestTools.UnitTesting;
using Seal.AI;
using Seal.Helpers;
using Seal.Model;
using System.Collections.Generic;
using System.Linq;
using System.Xml.Linq;

namespace Test
{
    /// <summary>
    /// Content accepted at the Metadata report code level: enumerated lists built from a column (SQL generated by the tool) and typed values of the view parameters rendered as code
    /// </summary>
    [TestClass]
    public class TestReportCodeLevelTypedValues
    {
        static Repository _repository;
        static MetaSource _northwind;

        [ClassInitialize]
        public static void Init(TestContext context)
        {
            _repository = Repository.Create();
            _northwind = _repository.Sources.First(i => i.Name == "Northwind");
        }

        static string ColumnGuid(string name) => _northwind.MetaData.Tables.SelectMany(i => i.Columns).First(i => i.Name == name).GUID;

        static string ReportXml(string enumXml, string viewParameters = "") => $@"<?xml version=""1.0""?>
<Report xmlns:xsi=""http://www.w3.org/2001/XMLSchema-instance"" xmlns:xsd=""http://www.w3.org/2001/XMLSchema"">
  <GUID>a</GUID><ViewGUID>b</ViewGUID>
  <Sources><ReportSource><GUID>c</GUID><Name>Northwind</Name><ConnectionGUID>1</ConnectionGUID>
    <MetaData><Enums>{enumXml}</Enums></MetaData><MetaSourceGUID>{_northwind.GUID}</MetaSourceGUID></ReportSource></Sources>
  <Views><ReportView><GUID>b</GUID><Name>View</Name><TemplateName>Report</TemplateName><Views>
    <ReportView><GUID>j</GUID><Name>Chart JS</Name><TemplateName>Chart JS</TemplateName><Parameters>{viewParameters}</Parameters></ReportView>
  </Views></ReportView></Views>
</Report>";

        static string Parameter(string name, string value) => $"<Parameter><Name>{name}</Name><Value>{System.Security.SecurityElement.Escape(value)}</Value></Parameter>";

        [TestMethod]
        public void EnumFromColumnAcceptedAtMetadata()
        {
            var doc = XDocument.Parse(ReportXml($"<MetaEnum><GUID>en1</GUID><Name>Cities</Name><FromColumnGUID>{ColumnGuid("Orders.ShipCity")}</FromColumnGUID></MetaEnum>"));
            var generated = new List<string>();
            Assert.IsNull(new AIReportWriter(null).ResolveEnumsFromColumns(doc, generated));
            Assert.AreEqual(1, generated.Count);
            var menum = doc.Descendants("MetaEnum").Single();
            Assert.IsNull(menum.Element("FromColumnGUID"));
            Assert.AreEqual("true", (string)menum.Element("IsDynamic"));
            StringAssert.Contains((string)menum.Element("Sql"), "SELECT DISTINCT");
            StringAssert.Contains((string)menum.Element("Sql"), "Orders.ShipCity");

            Assert.AreEqual(0, ReportCodeGuard.Check(doc.ToString(), null, ReportCodeLevel.Metadata, generated).Count);
        }

        [TestMethod]
        public void EnumSqlWrittenByTheAgentRefusedAtMetadata()
        {
            var xml = ReportXml("<MetaEnum><GUID>en1</GUID><Name>Cities</Name><IsDynamic>true</IsDynamic><Sql>SELECT DISTINCT Orders.ShipCity FROM Orders ORDER BY 1</Sql></MetaEnum>");
            var messages = ReportCodeGuard.Check(xml, null, ReportCodeLevel.Metadata);
            Assert.IsTrue(messages.Any(i => i.Contains("requires the Sql level")), string.Join("; ", messages));
            Assert.AreEqual(0, ReportCodeGuard.Check(xml, null, ReportCodeLevel.Sql).Count);
        }

        [TestMethod]
        public void EnumFromColumnErrors()
        {
            var doc = XDocument.Parse(ReportXml("<MetaEnum><GUID>en1</GUID><Name>Cities</Name><FromColumnGUID>00000000-0000-0000-0000-000000000001</FromColumnGUID></MetaEnum>"));
            StringAssert.Contains(new AIReportWriter(null).ResolveEnumsFromColumns(doc, new List<string>()), "is not a column of source");

            var mongo = _repository.Sources.FirstOrDefault(i => i.IsNoSQL);
            if (mongo != null)
            {
                doc = XDocument.Parse(ReportXml($"<MetaEnum><GUID>en1</GUID><Name>Years</Name><FromColumnGUID>{mongo.MetaData.Tables.SelectMany(i => i.Columns).First().GUID}</FromColumnGUID></MetaEnum>").Replace(_northwind.GUID, mongo.GUID));
                StringAssert.Contains(new AIReportWriter(null).ResolveEnumsFromColumns(doc, new List<string>()), "static list");
            }
        }

        [TestMethod]
        public void TypedViewParametersAcceptedAtMetadata()
        {
            var xml = ReportXml("", Parameter("chartjs_color_mappings", "'Excellente':'green','Insuffisante':'#ff0000','Moyenne':'rgba(255, 165, 0, 0.8)'")
                + Parameter("chartjs_colors", "['#1f77b4','green',\"hsl(120, 50%, 50%)\"]"));
            var messages = ReportCodeGuard.Check(xml, null, ReportCodeLevel.Metadata);
            Assert.AreEqual(0, messages.Count, string.Join("; ", messages));

            Assert.IsNull(ReportCodeGuard.CheckRawParameter("chartjs_color_mappings", "'Excellente':'green'", null, out string canonical));
            Assert.AreEqual("'Excellente':'green'", canonical);
            Assert.IsNull(ReportCodeGuard.CheckRawParameter("echarts_colors", "\"red\", #00ff00", null, out canonical));
            Assert.AreEqual("['red','#00ff00']", canonical);
            Assert.IsNull(ReportCodeGuard.CheckRawParameter("page_table_css", "color: rgba(0,0,0,0.5); font-weight:bold", null, out canonical));
            Assert.IsNull(ReportCodeGuard.CheckRawParameter("page_table_class", "table table-striped", null, out _));
            Assert.IsNull(ReportCodeGuard.CheckRawParameter("model_summary", "<b>Summary</b> of the <i>model</i>", null, out _));
            Assert.IsNull(ReportCodeGuard.CheckRawParameter("widget_exec_report", @"\Samples\05-Gauges.srex", null, out _));
        }

        [TestMethod]
        public void CodeInViewParametersRefusedAtMetadata()
        {
            foreach (var (name, value) in new[] {
                ("page_table_css", "background: url(http://x/y.png)"),
                ("page_table_css", "color: red\" onmouseover=\"alert(1)"),
                ("page_table_css", "width: expression(alert(1))"),
                ("chartjs_color_mappings", "'a':'green'};alert(1);{'b':'red'"),
                ("chartjs_color_mappings", "'</script><script>alert(1)':'green'"),
                ("chartjs_colors", "['red', alert(1)]"),
                ("chartjs_colors", "['javascript:alert(1)']"),
                ("page_table_class", "x\" onclick=\"alert(1)"),
                ("model_summary", "<img src=x onerror=alert(1)>"),
                ("additional_js", "alert(1)"),
                ("widget_exec_report", @"\Samples\NoSuchReport.srex"),
                ("widget_exec_report", @"\..\Settings\x.srex"),
                ("chartjs_title", "a'+alert(1)+'"),
            })
            {
                Assert.IsNotNull(ReportCodeGuard.CheckRawParameter(name, value, null, out _), $"{name}: {value}");
            }

            var xml = ReportXml("", Parameter("chartjs_color_mappings", "'a':'green'};alert(1);{'b':'red'"));
            Assert.IsTrue(ReportCodeGuard.Check(xml, null, ReportCodeLevel.Metadata).Any(i => i.Contains("chartjs_color_mappings")));
        }
    }
}
